func Retry(fn func() error, maxAttempts int) error {
	var err error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		if err = fn(); err == nil {
			return nil
		}
		backoff := time.Duration(attempt+1) * time.Second
		time.Sleep(backoff)
	}
	return fmt.Errorf("retry exhausted: %w", err)
}

